<script setup lang="ts">
// Serves the avif/webp copies generated by `npm run images:static` for a
// non-post image, falling back to the original. Post images use
// ResponsiveImage instead. See staticImageFormats.ts.
import { computed } from "vue";
import {
  isStaticImageConvertible,
  staticImageFormatSrc,
} from "@utils/staticImageFormats";

// Same as ResponsiveImage: attrs (class, alt, width, loading, @error, …)
// belong on the <img>, not the <picture> wrapper.
defineOptions({ inheritAttrs: false });

const { src } = defineProps<{
  // Root-absolute path to the original image, e.g. "/images/profile.png".
  src: string;
}>();

const convertible = computed(() => isStaticImageConvertible(src));
</script>

<template>
  <picture v-if="convertible">
    <source :srcset="staticImageFormatSrc(src, 'avif')" type="image/avif" />
    <source :srcset="staticImageFormatSrc(src, 'webp')" type="image/webp" />
    <img :src="src" v-bind="$attrs" />
  </picture>
  <img v-else :src="src" v-bind="$attrs" />
</template>
